WITH wanted AS (SELECT value->>'a' a, value->>'r' r, value->>'s' s, value->>'c' c, value->>'b' b, value->>'lo' lo, value->>'p' p FROM json_each(?)), evidence AS (SELECT w.*, MIN(h.price) low, COUNT(h.id) points, MIN(h.snapshot_at) first_at, MAX(h.snapshot_at) last_at, (SELECT h2.id FROM game_price_history h2 WHERE h2.appid = w.a AND h2.region_code = w.r AND h2.sub_id = w.s AND h2.currency = w.c AND h2.snapshot_at < w.b AND (w.lo IS NULL OR h2.snapshot_at >= w.lo) AND h2.price_status = 'ok' AND h2.price > 0 AND (h2.is_gold IS NULL OR h2.is_gold = 0) AND (h2.version_suffix IS NULL OR h2.version_suffix = '') AND (h2.is_bundle IS NULL OR h2.is_bundle = 0) AND (h2.product_unknown IS NULL OR h2.product_unknown = 0) AND (h2.source = 'steam' OR (h2.source = 'community' AND EXISTS (SELECT 1 FROM game_price_history k WHERE k.appid = h2.appid AND k.region_code = h2.region_code AND k.sub_id = h2.sub_id AND k.currency = h2.currency AND k.source = 'steam' AND k.price_status = 'ok' AND k.price > 0 AND k.snapshot_at <= w.b AND (k.is_gold IS NULL OR k.is_gold = 0) AND (k.version_suffix IS NULL OR k.version_suffix = '') AND (k.is_bundle IS NULL OR k.is_bundle = 0) AND (k.product_unknown IS NULL OR k.product_unknown = 0)))) ORDER BY h2.snapshot_at DESC, h2.id DESC LIMIT 1) prev_id FROM wanted w LEFT JOIN game_price_history h ON h.appid = w.a AND h.region_code = w.r AND h.sub_id = w.s AND h.currency = w.c AND h.snapshot_at < w.b AND (w.lo IS NULL OR h.snapshot_at >= w.lo) AND h.price_status = 'ok' AND h.price > 0 AND (h.is_gold IS NULL OR h.is_gold = 0) AND (h.version_suffix IS NULL OR h.version_suffix = '') AND (h.is_bundle IS NULL OR h.is_bundle = 0) AND (h.product_unknown IS NULL OR h.product_unknown = 0) AND (h.source = 'steam' OR (h.source = 'community' AND EXISTS (SELECT 1 FROM game_price_history k WHERE k.appid = h.appid AND k.region_code = h.region_code AND k.sub_id = h.sub_id AND k.currency = h.currency AND k.source = 'steam' AND k.price_status = 'ok' AND k.price > 0 AND k.snapshot_at <= w.b AND (k.is_gold IS NULL OR k.is_gold = 0) AND (k.version_suffix IS NULL OR k.version_suffix = '') AND (k.is_bundle IS NULL OR k.is_bundle = 0) AND (k.product_unknown IS NULL OR k.product_unknown = 0)))) GROUP BY w.a,w.r,w.s,w.c), latest AS (SELECT e.*, (SELECT s.id FROM game_price_history s WHERE s.appid=e.a AND s.region_code=e.r AND s.sub_id=e.s AND s.currency=e.c AND s.source='steam' AND s.price_status='ok' AND s.price>0 AND (s.is_gold IS NULL OR s.is_gold = 0) AND (s.version_suffix IS NULL OR s.version_suffix = '') AND (s.is_bundle IS NULL OR s.is_bundle = 0) AND (s.product_unknown IS NULL OR s.product_unknown = 0) AND s.snapshot_at<=e.b ORDER BY s.snapshot_at DESC,s.id DESC LIMIT 1) steam_id FROM evidence e) SELECT e.a,e.r,e.s,e.c,e.low,e.points,e.first_at,e.last_at, p.price,p.original_price,p.cny_fen,p.snapshot_at,p.source,p.id, EXISTS (SELECT 1 FROM game_current_prices cp WHERE cp.appid=e.a AND cp.region_code=e.r AND cp.sub_id=e.s AND cp.currency=e.c AND cp.price=e.p AND cp.updated_at=e.b AND cp.last_success_at=cp.updated_at AND cp.price_status='ok' AND cp.attempt_outcome='success' AND cp.steam_answer='ok' AND cp.price=(SELECT price FROM game_price_history WHERE id=e.steam_id)) current_known, e.steam_id FROM latest e LEFT JOIN game_price_history p ON p.id=e.prev_id
